package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

type PartRec struct {
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

var WsEofFlag string // PIC X len=1 = "N"
var WsLabel string   // PIC X(20) len=20 = SPACES
var WsACount int64   // PIC 99 len=2 = 0
var WsTotalA int64   // PIC 999 len=3 = 0
var WsCount int64    // PIC 999 len=3 = 0

var curRec PartRec
var inputLines []string
var inputIdx int

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func padRight(s string, n int) string {
	if len(s) > n {
		return s[:n]
	}
	if len(s) < n {
		return s + strings.Repeat(" ", n-len(s))
	}
	return s
}

func formatUnsigned(n int64, width int) string {
	if n < 0 {
		n = -n
	}
	mod := int64(1)
	for i := 0; i < width; i++ {
		mod *= 10
	}
	n = n % mod
	s := fmt.Sprintf("%d", n)
	if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	}
	if len(s) > width {
		s = s[len(s)-width:]
	}
	return s
}

func storePic(n int64, digits int) int64 {
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	// keep low-order digits, preserve sign behaviour for non-negative use
	if n >= 0 {
		return n % mod
	}
	// for negative, COBOL keeps sign + low order digits; emulate truncation toward zero
	return -((-n) % mod)
}

func delimitedBySpace(s string) string {
	if i := strings.IndexByte(s, ' '); i >= 0 {
		return s[:i]
	}
	return s
}

func parseSerial(s string) int64 {
	s = padRight(s, 4)
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	// keep only digits sign? input should be digits
	var v int64
	for i := 0; i < len(t); i++ {
		c := t[i]
		if c >= '0' && c <= '9' {
			v = v*10 + int64(c-'0')
		}
	}
	return storePic(v, 4)
}

func MainPara() {
	WsEofFlag = "N"
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	WsTotalA = 0
	WsCount = 0

	f, err := os.Open("input.dat")
	if err != nil {
		// COBOL OPEN INPUT on missing file: treat as empty (AT END immediately)
		inputLines = nil
		inputIdx = 0
	} else {
		sc := bufio.NewScanner(f)
		// allow long lines
		sc.Buffer(make([]byte, 0, 64*1024), 1024*1024)
		var lines []string
		for sc.Scan() {
			line := sc.Text()
			// bufio.Scanner already strips \r\n and \n; but strip trailing \r if any
			if len(line) > 0 && line[len(line)-1] == '\r' {
				line = line[:len(line)-1]
			}
			lines = append(lines, line)
		}
		f.Close()
		inputLines = lines
		inputIdx = 0
	}
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	SummaryPara()
}

func ReadPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	// pad with spaces to 15, truncate if longer
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	part := line[0:8]
	region := line[8:11]
	serialStr := line[11:15]
	curRec.LbPart = part
	curRec.LbRegion = region
	curRec.LbSerial = parseSerial(serialStr)
}

func ProcessPara() {
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	cnt := int64(0)
	p := padRight(curRec.LbPart, 8)
	for i := 0; i < len(p); i++ {
		if p[i] == 'A' {
			cnt++
		}
	}
	WsACount = storePic(cnt, 2)

	regionPart := delimitedBySpace(padRight(curRec.LbRegion, 3))
	partPart := delimitedBySpace(padRight(curRec.LbPart, 8))
	serialStr := formatUnsigned(curRec.LbSerial, 4)

	combined := regionPart + "-" + partPart + "-" + serialStr
	if len(combined) > 20 {
		combined = combined[:20]
	} else {
		combined = combined + strings.Repeat(" ", 20-len(combined))
	}
	WsLabel = combined
	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")
	WsLabel = padRight(WsLabel, 20)

	WsTotalA = storePic(WsTotalA+WsACount, 3)
	WsCount = storePic(WsCount+1, 3)
	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	out := padRight(WsLabel, 20) + " A=" + formatUnsigned(WsACount, 2)
	fmt.Fprintln(os.Stdout, out)
	ReadPara()
}

func SummaryPara() {
	out := "LABELS: " + formatUnsigned(WsCount, 3) + " A-TOTAL: " + formatUnsigned(WsTotalA, 3)
	fmt.Fprintln(os.Stdout, out)
}

func main() {
	MainPara()
}
